type aaa_history_u002D_status =
    | [<System.Text.Json.Serialization.JsonName "exact">] Exact
    | [<System.Text.Json.Serialization.JsonName "approximate">] Approximate
    | [<System.Text.Json.Serialization.JsonName "unavailable">] Unavailable

    member this.Format() =
        match this with
        | Exact -> "exact"
        | Approximate -> "approximate"
        | Unavailable -> "unavailable"

