///Version percentage distribution. Only present for "new_instances" strategy.
///For "rolling" strategy, see progress.version_distribution instead.
type Version_distribution =
    {
        ///Percentage of instances on the current (old) version.
        current_version_percentage: int
        ///Percentage of instances on the target (new) version.
        target_version_percentage: int
    }

    ///Creates an instance of Version_distribution with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(current_version_percentage: int, target_version_percentage: int): Version_distribution =
        { current_version_percentage = current_version_percentage
          target_version_percentage = target_version_percentage }

///Represents the status and metadata of a rollout process for an application.
///For "rolling" strategy: includes steps and progress with instance counts.
///For "new_instances" strategy: the response omits steps and progress. Use percentage,
///version_distribution, and health.summary for status.
type cc_ApplicationRollout =
    {
        ///UTC timestamp string in ISO 8601 format.
        created_at: cc_ISO8601Timestamp
        ///User-specified container configuration changes.
        current_configuration: cc_ModifyUserDeploymentConfiguration
        ///Current application version before the rollout.
        current_version: int
        description: string
        health: cc_ApplicationHealth
        ///An identifier for a specific rollout within an application.
        id: cc_RolloutID
        ///Kind of the rollout process.
        /// - "full_auto": For rolling rollouts, starts progressing steps upon rollout creation. For new_instances rollouts, advances percentage targets automatically after target-version health is observed.
        /// - "full_manual": Requires manually progressing each step in the rollout using the UpdateRollout's action paramater.
        /// - "durable_objects_auto": Default when the application is a DO application.
        kind: cc_ApplicationRolloutKind
        ///Timestamp of the most recent update to status, health, or progress.
        last_updated_at: cc_ISO8601Timestamp
        ///Current target version percentage (0-100). Only present for "new_instances" strategy.
        percentage: Option<int>
        ///Progress details of an application rollout.
        progress: Option<cc_ApplicationRolloutProgress>
        ///Timestamp when the rollout started.
        started_at: Option<System.DateTimeOffset>
        ///Current status of the rollout.
        status: cc_ApplicationRolloutStatus
        steps: Option<list<cc_RolloutStep>>
        ///The rollout strategy.
        ///- "rolling": Step-based rollout with health gates. Actively replaces instances to reach each step's target percentage. Response includes steps and progress.
        ///- "new_instances": Percentage control over version distribution. Version sync actively replaces instances to match the configured percentage. "full_auto" ramps through fixed percentage targets after target-version health is observed. Response includes percentage, version_distribution, and health.summary.
        strategy: Strategy
        ///User-specified container configuration changes.
        target_configuration: cc_ModifyUserDeploymentConfiguration
        ///Target application version after the rollout is complete and applied to all current instances.
        target_version: int
        ///Version percentage distribution. Only present for "new_instances" strategy.
        ///For "rolling" strategy, see progress.version_distribution instead.
        version_distribution: Option<Version_distribution>
    }

    ///Creates an instance of cc_ApplicationRollout with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(created_at: cc_ISO8601Timestamp,
                         current_configuration: cc_ModifyUserDeploymentConfiguration,
                         current_version: int,
                         description: string,
                         health: cc_ApplicationHealth,
                         id: cc_RolloutID,
                         kind: cc_ApplicationRolloutKind,
                         last_updated_at: cc_ISO8601Timestamp,
                         status: cc_ApplicationRolloutStatus,
                         strategy: Strategy,
                         target_configuration: cc_ModifyUserDeploymentConfiguration,
                         target_version: int): cc_ApplicationRollout =
        { created_at = created_at
          current_configuration = current_configuration
          current_version = current_version
          description = description
          health = health
          id = id
          kind = kind
          last_updated_at = last_updated_at
          percentage = None
          progress = None
          started_at = None
          status = status
          steps = None
          strategy = strategy
          target_configuration = target_configuration
          target_version = target_version
          version_distribution = None }

///Expected distribution of instances per version, based on the current percentage split.
///Populated during active rollouts. Values derive from the version percentage weights
///rather than actual running instance counts.
type cc_ApplicationRolloutProgressVersion_distribution =
    {
        ///Expected number of instances remaining on the current (old) version based on the current percentage split. Only populated for "rolling" strategy.
        current_version_instances: Option<int>
        ///The percentage of new instances being scheduled on the current version (100 - target_version_percentage).
        ///Only populated for "new_instances" strategy.
        current_version_percentage: Option<int>
        ///Expected number of instances scheduled for the target (new) version based on the current percentage split. Only populated for "rolling" strategy.
        target_version_instances: Option<int>
        ///The active percentage of new instances being scheduled on the target version.
        ///For "rolling", this reflects the step_size.percentage of the current active step.
        ///For "new_instances", this reflects the user-set percentage.
        target_version_percentage: Option<int>
    }

    ///Creates an instance of cc_ApplicationRolloutProgressVersion_distribution with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(): cc_ApplicationRolloutProgressVersion_distribution =
        { current_version_instances = None
          current_version_percentage = None
          target_version_instances = None
          target_version_percentage = None }

///Progress details of an application rollout.
type cc_ApplicationRolloutProgress =
    {
        ///Current step being executed in the rollout process. Initialized to 0.
