[<RequireQualifiedAccess>]
type cc_RolloutStepStatus =
    | [<System.Text.Json.Serialization.JsonName "pending">] Pending
    | [<System.Text.Json.Serialization.JsonName "progressing">] Progressing
    | [<System.Text.Json.Serialization.JsonName "reverting">] Reverting
    | [<System.Text.Json.Serialization.JsonName "completed">] Completed
    | [<System.Text.Json.Serialization.JsonName "reverted">] Reverted

    member this.Format() =
        match this with
        | Pending -> "pending"
        | Progressing -> "progressing"
        | Reverting -> "reverting"
        | Completed -> "completed"
        | Reverted -> "reverted"

