type Latest_upload_status =
    | [<System.Text.Json.Serialization.JsonName "Mirroring">] Mirroring
    | [<System.Text.Json.Serialization.JsonName "Unifying">] Unifying
    | [<System.Text.Json.Serialization.JsonName "Loading">] Loading
    | [<System.Text.Json.Serialization.JsonName "Provisioning">] Provisioning
    | [<System.Text.Json.Serialization.JsonName "Complete">] Complete
    | [<System.Text.Json.Serialization.JsonName "Error">] Error

    member this.Format() =
        match this with
        | Mirroring -> "Mirroring"
        | Unifying -> "Unifying"
        | Loading -> "Loading"
        | Provisioning -> "Provisioning"
        | Complete -> "Complete"
        | Error -> "Error"

