[<RequireQualifiedAccess>]
type email_u002D_auth_SpfComponentType =
    | [<System.Text.Json.Serialization.JsonName "ALL">] ALL
    | [<System.Text.Json.Serialization.JsonName "A">] A
    | [<System.Text.Json.Serialization.JsonName "MX">] MX
    | [<System.Text.Json.Serialization.JsonName "IP4">] IP4
    | [<System.Text.Json.Serialization.JsonName "IP6">] IP6
    | [<System.Text.Json.Serialization.JsonName "EXISTS">] EXISTS
    | [<System.Text.Json.Serialization.JsonName "INCLUDE">] INCLUDE
    | [<System.Text.Json.Serialization.JsonName "PTR">] PTR
    | [<System.Text.Json.Serialization.JsonName "REDIRECT">] REDIRECT

    member this.Format() =
        match this with
        | ALL -> "ALL"
        | A -> "A"
        | MX -> "MX"
        | IP4 -> "IP4"
        | IP6 -> "IP6"
        | EXISTS -> "EXISTS"
        | INCLUDE -> "INCLUDE"
        | PTR -> "PTR"
        | REDIRECT -> "REDIRECT"

///A single SPF component (mechanism) in the inspection tree.
///The `value` field includes the qualifier prefix (e.g., "-all", "~mx:example.com")
///to match the raw SPF record syntax. The qualifier is also available separately
///in the `result` field for programmatic access.
type email_u002D_auth_SpfComponent =
    {
        ///Number of DNS lookups this component requires (per RFC 7208).
        ///- MX, A, EXISTS, INCLUDE, REDIRECT, PTR: 1
        ///- IP4, IP6, ALL: 0
        lookup_count: int
        ///Nested SPF tree for INCLUDE or REDIRECT mechanisms.
        ///Only present for INCLUDE/REDIRECT components.
        nested: Option<email_u002D_auth_SpfTree>
        ///SPF mechanism result qualifier
        result: email_u002D_auth_SpfResult
        ///Component type (UPPERCASE)
        [<System.Text.Json.Serialization.JsonPropertyName "type">]
        type_: email_u002D_auth_SpfComponentType
        ///Component value with qualifier prefix.
        ///For IP4/IP6, stores just the IP address (no "ip4:" or "ip6:" prefix).
        ///Examples: "203.0.113.1", "203.0.113.0/24", "2001:db8::1/64", "-all", "~mx:example.com", "include:_spf.example.com"
        value: string
    }

    ///Creates an instance of email_u002D_auth_SpfComponent with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(lookup_count: int,
                         result: email_u002D_auth_SpfResult,
                         type_: email_u002D_auth_SpfComponentType,
                         value: string): email_u002D_auth_SpfComponent =
        { lookup_count = lookup_count
          nested = None
          result = result
          type_ = type_
          value = value }

///Recursive SPF inspection tree
type email_u002D_auth_SpfTree =
    {
        ///Parsed SPF components (mechanisms)
        components: list<email_u002D_auth_SpfComponent>
        ///Domain being inspected
        domain: string
        ///All errors encountered during inspection, collected from the entire tree.
        ///This includes errors from nested includes at any depth, providing a quick
        ///overview of all issues without needing to traverse the nested structure.
        ///Each error includes a `domain` field to identify where it occurred.
        ///Empty array if no errors (omitted from JSON when empty).
        errors: Option<list<email_u002D_auth_InspectError>>
        ///Raw SPF record content
        record: string
        ///Total number of DNS lookups performed across all includes
        total_lookups: int
    }

    ///Creates an instance of email_u002D_auth_SpfTree with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(components: list<email_u002D_auth_SpfComponent>,
                         domain: string,
                         record: string,
                         total_lookups: int): email_u002D_auth_SpfTree =
        { components = components
          domain = domain
          errors = None
          record = record
          total_lookups = total_lookups }

///Live DNS records for the zone, grouped by type
type email_u002D_auth_ZoneDnsRecords =
    {
        ///BIMI TXT records
        bimi_records: Option<list<email_u002D_auth_DnsRecordInfo>>
