type magic_interconnect_health_checkRate =
    | [<System.Text.Json.Serialization.JsonName "low">] Low
    | [<System.Text.Json.Serialization.JsonName "mid">] Mid
    | [<System.Text.Json.Serialization.JsonName "high">] High

    member this.Format() =
        match this with
        | Low -> "low"
        | Mid -> "mid"
        | High -> "high"

[<RequireQualifiedAccess>]
type magic_interconnect_health_checkType =
    | [<System.Text.Json.Serialization.JsonName "reply">] Reply
    | [<System.Text.Json.Serialization.JsonName "request">] Request

    member this.Format() =
        match this with
        | Reply -> "reply"
        | Request -> "request"

[<RequireQualifiedAccess>]
type Direction =
    | [<System.Text.Json.Serialization.JsonName "unidirectional">] Unidirectional
    | [<System.Text.Json.Serialization.JsonName "bidirectional">] Bidirectional

    member this.Format() =
        match this with
        | Unidirectional -> "unidirectional"
        | Bidirectional -> "bidirectional"

