    | [<System.Text.Json.Serialization.JsonName "ConfigureCloudflaredTunnel">] ConfigureCloudflaredTunnel
    | [<System.Text.Json.Serialization.JsonName "RekeyInstallBoth">] RekeyInstallBoth
    | [<System.Text.Json.Serialization.JsonName "RekeyStart">] RekeyStart
    | [<System.Text.Json.Serialization.JsonName "RekeyRestart">] RekeyRestart
