    member this.Format() =
        match this with
        | Init -> "Init"
        | Leave -> "Leave"
        | StartAttestation -> "StartAttestation"
        | FinishAttestationSuccess -> "FinishAttestationSuccess"
        | FinishAttestationFailure -> "FinishAttestationFailure"
        | StartRotateCryptKey -> "StartRotateCryptKey"
        | FinishRotateCryptKeySuccess -> "FinishRotateCryptKeySuccess"
