        | RekeyInstallBoth -> "RekeyInstallBoth"
        | RekeyStart -> "RekeyStart"
        | RekeyRestart -> "RekeyRestart"
        | RekeyAdvance -> "RekeyAdvance"
        | RekeyComplete -> "RekeyComplete"
        | RekeyReset -> "RekeyReset"
        | HaTransition -> "HaTransition"
