    | [<System.Text.Json.Serialization.JsonName "admin-read-only">] AdminReadOnly
    | [<System.Text.Json.Serialization.JsonName "object-read-write">] ObjectReadWrite
    | [<System.Text.Json.Serialization.JsonName "object-read-only">] ObjectReadOnly

    member this.Format() =
        match this with
        | AdminReadWrite -> "admin-read-write"
        | AdminReadOnly -> "admin-read-only"
        | ObjectReadWrite -> "object-read-write"
        | ObjectReadOnly -> "object-read-only"

type r2_temp_access_creds_request =
    {
        ///Name of the R2 bucket.
        bucket: string
        ///Optional object paths to scope the credentials to.
        objects: Option<list<string>>
        ///The parent access key id to use for signing.
        parentAccessKeyId: string
        ///Permissions allowed on the credentials.
        permission: Permission
        ///Optional prefix paths to scope the credentials to.
        prefixes: Option<list<string>>
        ///How long the credentials will live for in seconds.
        ttlSeconds: float
    }

    ///Creates an instance of r2_temp_access_creds_request with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(bucket: string, parentAccessKeyId: string, permission: Permission, ttlSeconds: float):
        r2_temp_access_creds_request =
        { bucket = bucket
          objects = None
          parentAccessKeyId = parentAccessKeyId
          permission = permission
          prefixes = None
          ttlSeconds = ttlSeconds }

type r2_temp_access_creds_response =
    {
        ///ID for new access key.
        accessKeyId: Option<string>
        ///Secret access key.
        secretAccessKey: Option<string>
        ///Security token.
        sessionToken: Option<string>
    }

    ///Creates an instance of r2_temp_access_creds_response with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(): r2_temp_access_creds_response =
        { accessKeyId = None
          secretAccessKey = None
          sessionToken = None }

type r2_v4_response =
    {
        errors: r2_errors
        messages: r2_messages
        result: System.Text.Json.Nodes.JsonObject
        ///Whether the API call was successful.
        success: bool
    }

    ///Creates an instance of r2_v4_response with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(errors: r2_errors,
                         messages: r2_messages,
                         result: System.Text.Json.Nodes.JsonObject,
                         success: bool): r2_v4_response =
        { errors = errors
          messages = messages
          result = result
          success = success }

type r2_v4_response_failure =
