[<RequireQualifiedAccess>]
type realtimekit_ActiveSessionType =
    | [<System.Text.Json.Serialization.JsonName "meeting">] Meeting
    | [<System.Text.Json.Serialization.JsonName "livestream">] Livestream
    | [<System.Text.Json.Serialization.JsonName "participant">] Participant

    member this.Format() =
        match this with
        | Meeting -> "meeting"
        | Livestream -> "livestream"
        | Participant -> "participant"

type realtimekit_ActiveSession =
    {
        ///ID of the meeting this session is associated with. In the case of V2 meetings, it is always a UUID. In V1 meetings, it is a room name of the form `abcdef-ghijkl`
        associated_id: string
        breakout_rooms: Option<list<realtimekit_ActiveSession>>
        ///timestamp when session created
        created_at: string
        ///timestamp when session ended
        ended_at: Option<string>
        ///ID of the session
        id: string
        ///number of participants currently in the session
        live_participants: float
        ///number of maximum participants that were in the session
        max_concurrent_participants: float
        ///Title of the meeting this session belongs to
        meeting_display_name: string
        ///number of minutes consumed since the session started
        minutes_consumed: float
        ///App id that hosted this session
        organization_id: string
        ///timestamp when session started
        started_at: string
        ///current status of session
        status: realtimekit_ActiveSessionStatus
        ///type of session
        [<System.Text.Json.Serialization.JsonPropertyName "type">]
        type_: realtimekit_ActiveSessionType
        ///timestamp when session was last updated
        updated_at: string
    }

    ///Creates an instance of realtimekit_ActiveSession with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(associated_id: string,
                         created_at: string,
                         id: string,
                         live_participants: float,
                         max_concurrent_participants: float,
                         meeting_display_name: string,
                         minutes_consumed: float,
                         organization_id: string,
                         started_at: string,
                         status: realtimekit_ActiveSessionStatus,
                         type_: realtimekit_ActiveSessionType,
                         updated_at: string): realtimekit_ActiveSession =
        { associated_id = associated_id
          breakout_rooms = None
          created_at = created_at
          ended_at = None
          id = id
          live_participants = live_participants
          max_concurrent_participants = max_concurrent_participants
          meeting_display_name = meeting_display_name
          minutes_consumed = minutes_consumed
          organization_id = organization_id
          started_at = started_at
          status = status
          type_ = type_
          updated_at = updated_at }

