[<RequireQualifiedAccess>]
type UrlscannerCreateScanPayloadVisibility =
    | [<System.Text.Json.Serialization.JsonName "Public">] Public
    | [<System.Text.Json.Serialization.JsonName "Unlisted">] Unlisted

    member this.Format() =
        match this with
        | Public -> "Public"
        | Unlisted -> "Unlisted"

type UrlscannerCreateScanPayload =
    {
        ///Country to geo egress from
        country: Option<Country>
        ///Set custom headers.
        customHeaders: Option<Map<string, string>>
        ///Take multiple screenshots targeting different device types.
        screenshotsResolutions: Option<list<ScreenshotsResolutions>>
        url: string
        ///The option `Public` means it will be included in listings like recent scans and search results. `Unlisted` means it will not be included in the aforementioned listings, users will need to have the scan's ID to access it. A a scan will be automatically marked as unlisted if it fails, if it contains potential PII or other sensitive material.
        visibility: Option<UrlscannerCreateScanPayloadVisibility>
    }

    ///Creates an instance of UrlscannerCreateScanPayload with all optional fields initialized to None. The required fields are parameters of this function
    static member Create(url: string): UrlscannerCreateScanPayload =
        { country = None
          customHeaders = None
          screenshotsResolutions = None
          url = url
          visibility = None }

type UrlscannerCreateScan_OKErrors = { message: string }
type UrlscannerCreateScan_OKMessages = { message: string }

[<RequireQualifiedAccess>]
type UrlscannerCreateScan_OKResultVisibility =
    | [<System.Text.Json.Serialization.JsonName "public">] Public
    | [<System.Text.Json.Serialization.JsonName "unlisted">] Unlisted

    member this.Format() =
        match this with
        | Public -> "public"
        | Unlisted -> "unlisted"

type UrlscannerCreateScan_OKResult =
    {
        ///Time when url was submitted for scanning.
        time: System.DateTimeOffset
        ///Canonical form of submitted URL. Use this if you want to later search by URL.
        url: string
        ///Scan ID.
        uuid: System.Guid
        ///Submitted visibility status.
        visibility: UrlscannerCreateScan_OKResultVisibility
    }

type UrlscannerCreateScan_OK =
    { errors: list<UrlscannerCreateScan_OKErrors>
      messages: list<UrlscannerCreateScan_OKMessages>
      result: UrlscannerCreateScan_OKResult
      success: bool }

